/// <summary>
/// Determines if concurrent deletes should throw exception.
/// </summary>
/// <returns>true, if exception should be thrown; otherwise, false.</returns>
public boolean shouldThrowExceptionOnZeroDelete()
{
    return true;
}

public boolean validateWrite()
{
    boolean ret;

    ret = super();

    ret = ret 
        && this.validateBirthAndDeathDate();

    return ret;
}

public boolean validateBirthAndDeathDate()
{
    if (this.DeathDate > dateNull()
        && this.BirthDate > this.DeathDate)
    {
        return checkfailed("@ITFormacion:DeathDateMustBeLaterThanBirthDate");
    }

    return true;
}

public void modifiedField(FieldId _fieldId)
{
    super(_fieldId);

    switch (_fieldId)
    {
        case fieldNum(JIStmpAuthorTable, IsDead):
            this.modifiedIsDead();
            break;
        case fieldNum (JIStmpAuthorTable, BirthDate):
            //this.modifiedBirthDate();
            //break
    }

}

public void modifiedIsDead()
{
    if (!this.IsDead)
    {
        this.DeathDate = dateNull();
    }

    this.setDeathDateEditableInForm();
}

public void setDeathDateEditableInForm()
{
    FormDataSource formDatasource = FormDataUtil::getFormDataSource(this);

    if (formDataSource)
    {
        formDataSource.object(fieldNum(JIStmpAuthorTable, DeathDate)).allowEdit(this.IsDead);
    }    
}

public void initFromAuthorTable(JISAuthorTable _authorTable)
{
    this.Id         = _authorTable.Id;
    this.BirthDate  = _authorTable.BirthDate; 
    this.DeathDate  = _authorTable.DeathDate; 
    this.FirstName  = _authorTable.FirstName; 
    this.LastName   = _authorTable.LastName;  
    this.IsDead     = _authorTable.IsDead;    
}
